package com.reservedbytes.cinema_reservation;
import com.reservedbytes.cinema_reservation.model.*;
import com.reservedbytes.cinema_reservation.service.*;
import com.reservedbytes.cinema_reservation.service.CinemaManagement.*;
import com.reservedbytes.cinema_reservation.repository.*;
import com.reservedbytes.cinema_reservation.dto.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @Transactional class CinemaManagementTests {
 @Autowired CinemaManagement c;
 @Autowired ReservationService booking;
 @Autowired UserRepository users;
 Movie movie; CinemaHall hall; List<Seat> seats; Instant start; User user;
 @BeforeEach void setup(){movie=c.saveMovie(null,new MovieInput("New movie","Description","Drama",120,2026,"https://example.com/poster.jpg",true));hall=c.saveHall(null,new HallInput("Test "+UUID.randomUUID(),true));seats=c.layout(hall.getId(),new LayoutInput(8,10));start=Instant.now().plusSeconds(86400);user=users.save(new User());}
 @Test void movieAndHallEditingAndLayout(){assertThat(seats).hasSize(80);assertThat(seats.get(79).getRowNumber()).isEqualTo(8);c.saveMovie(movie.getId(),new MovieInput("Edited","New description","Thriller",90,2025,"",false));assertThat(movie.getTitle()).isEqualTo("Edited");assertThat(movie.isActive()).isFalse();c.saveHall(hall.getId(),new HallInput("Renamed "+UUID.randomUUID(),true));assertThat(hall.getName()).startsWith("Renamed");c.configureSeat(hall.getId(),seats.get(0).getId(),new SeatInput(Seat.SeatType.VIP,false));assertThat(seats.get(0).getSeatType()).isEqualTo(Seat.SeatType.VIP);assertThat(seats.get(0).isActive()).isFalse();}
 @Test void overlapAndAdjacentShowings(){var s=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start));assertThatThrownBy(()->c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start.plusSeconds(60)))).hasMessageContaining("overlap");var next=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),s.getEndsAt()));assertThat(next.getStartsAt()).isEqualTo(s.getEndsAt());}
 @Test void sameSeatDifferentScreeningsAndConflictWithinScreening(){var a=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start));var b=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start.plusSeconds(10000)));Long seat=seats.get(0).getId();var r=booking.create(new CreateReservationRequest(user.getId(),a.getId(),List.of(seat)));assertThat(booking.confirm(r.id(),user.getId()).status()).isEqualTo(ReservationStatus.CONFIRMED);assertThat(booking.availability(a.getId()).get(0).availability()).isEqualTo("UNAVAILABLE");assertThat(booking.availability(b.getId()).get(0).availability()).isEqualTo("AVAILABLE");var other=booking.create(new CreateReservationRequest(user.getId(),b.getId(),List.of(seat)));assertThat(booking.confirm(other.id(),user.getId()).status()).isEqualTo(ReservationStatus.CONFIRMED);var conflict=booking.create(new CreateReservationRequest(user.getId(),a.getId(),List.of(seat)));assertThatThrownBy(()->booking.confirm(conflict.id(),user.getId())).hasMessageContaining("already held");assertThatThrownBy(()->c.layout(hall.getId(),new LayoutInput(2,2))).hasMessageContaining("history");assertThatThrownBy(()->c.saveScreening(a.getId(),new ScreeningInput(movie.getId(),hall.getId(),start.plusSeconds(100)))).hasMessageContaining("history");assertThatThrownBy(()->c.configureSeat(hall.getId(),seat,new SeatInput(Seat.SeatType.VIP,true))).hasMessageContaining("history");}
 @Test void vipApprovalAndDisabledSeat(){var vip=seats.get(0);c.configureSeat(hall.getId(),vip.getId(),new SeatInput(Seat.SeatType.VIP,true));c.configureSeat(hall.getId(),seats.get(1).getId(),new SeatInput(Seat.SeatType.STANDARD,false));var s=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start));assertThat(booking.availability(s.getId()).get(1).availability()).isEqualTo("DISABLED");assertThatThrownBy(()->booking.create(new CreateReservationRequest(user.getId(),s.getId(),List.of(seats.get(1).getId())))).hasMessageContaining("Seats must");var r=booking.create(new CreateReservationRequest(user.getId(),s.getId(),List.of(vip.getId())));assertThat(booking.confirm(r.id(),user.getId()).status()).isEqualTo(ReservationStatus.PENDING_APPROVAL);assertThat(booking.approval(r.id(),3L,new ApprovalRequest("APPROVE")).status()).isEqualTo(ReservationStatus.CONFIRMED);}
 @Test void invalidOperationsAndCancellation(){assertThatThrownBy(()->c.layout(hall.getId(),new LayoutInput(0,10))).hasMessageContaining("rows");assertThatThrownBy(()->c.saveMovie(null,new MovieInput("","","",0,2026,"",true))).hasMessageContaining("Title");assertThatThrownBy(()->c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),Instant.now().minusSeconds(10)))).hasMessageContaining("future");var s=c.saveScreening(null,new ScreeningInput(movie.getId(),hall.getId(),start));assertThatThrownBy(()->c.deleteMovie(movie.getId())).hasMessageContaining("screenings");c.cancelScreening(s.getId());assertThatThrownBy(()->booking.create(new CreateReservationRequest(user.getId(),s.getId(),List.of(seats.get(0).getId())))).hasMessageContaining("unavailable");}
}
